mapper.select:
SELECT
    e.id AS eventId,
    e.event_type AS eventType,
    COALESCE(NULLIF(e.scene_code, ''), e.event_type) AS sceneCode,
    e.biz_type AS bizType,
    e.biz_id AS bizId,
    e.biz_no AS bizNo,
    e.status AS eventStatus,
    e.retry_count AS eventRetryCount,
    e.error_message AS eventErrorMessage,
    e.create_time AS createTime,
    e.update_time AS updateTime
FROM sys_notify_event e


        AND e.biz_type = #{query.bizType}


        AND e.biz_id = #{query.bizId}


        AND e.biz_no LIKE CONCAT('%', #{query.bizNo}, '%')


        AND COALESCE(NULLIF(e.scene_code, ''), e.event_type) = #{query.sceneCode}


        AND (
            EXISTS (
                SELECT 1
                FROM sys_notify_message sm
                WHERE sm.event_id = e.id
                  AND (
                      sm.target_type = #{query.targetType}
                      OR sm.message_type = #{query.targetType}
                  )
            )
            OR EXISTS (
                SELECT 1
                FROM sys_notify_dispatch sd
                WHERE sd.event_id = e.id
                  AND (
                      sd.target_type = #{query.targetType}
                      OR sd.channel_type = #{query.targetType}
                  )
            )
        )


        AND e.status = #{query.eventStatus}


        AND EXISTS (
            SELECT 1
            FROM sys_notify_dispatch sd
            WHERE sd.event_id = e.id
              AND sd.dispatch_status = #{query.dispatchStatus}
        )


        AND EXISTS (
            SELECT 1
            FROM sys_notify_dispatch sd
            WHERE sd.event_id = e.id
              AND sd.result_code = #{query.resultCode}
        )


        AND e.create_time >= #{query.beginTime}


        AND e.create_time <= #{query.endTime}


ORDER BY e.create_time DESC, e.id DESC
